<script setup lang="ts">
/**
 * AppShell.NavItem: a row of the rail, start-aligned, a link or a button.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/app-shell.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, inject } from 'vue'

import { Icon, useListening, type IconRole } from '@polymorph/vue'
import styles from '@polymorph/recipes/archetypes/app-shell.module.css'
import Tooltip from '../overlays/Tooltip.vue'

export interface AppShellNavItemProps {
  /**
   * Expected in practice, because a collapsed rail is unusable without icons.
   */
  icon?: IconRole
  /**
   * The accessible name in every mode, including collapsed.
   */
  label: string
  /**
   * Marks the current page, with exactly one per rail.
   */
  current?: boolean
  /**
   * With an `href`, the row is an `<a>` with Link's semantics and NavItem's styling.
   */
  href?: string
}

defineOptions({ name: 'AppShellNavItem', inheritAttrs: false })

const props = withDefaults(defineProps<AppShellNavItemProps>(), { current: false })
const emit = defineEmits<{ navigate: [href: string]; select: [] }>()
defineSlots<{ end?: (props: Record<string, never>) => unknown }>()
const listening = useListening()
const owner = inject<Record<string, any>>('polymorph:AppShell', {})
const navigatesHere = computed(
  () =>
    (event: MouseEvent): boolean =>
      !event.defaultPrevented &&
      event.button === 0 &&
      !event.metaKey &&
      !event.ctrlKey &&
      !event.shiftKey &&
      !event.altKey,
)
const route = computed(() => (event: MouseEvent): void => {
  if (props.href === undefined || !listening.navigate || !navigatesHere.value(event)) return
  event.preventDefault()
  emit('navigate', props.href)
})
</script>

<template>
  <Tooltip v-if="owner.collapsed === true" :content="label" side="right">
    <!-- row -->
    <button
      v-if="href === undefined"
      :class="styles.navItem"
      type="button"
      :aria-current="current ? 'page' : undefined"
      :data-current="current ? '' : undefined"
      @click="emit('select')"
    >
      <!-- glyph -->
      <span v-if="icon !== undefined" :class="styles.navGlyph">
        <Icon :name="icon" />
      </span>
      <!-- label -->
      <span :class="styles.navLabel">
        {{ label }}
      </span>
      <!-- end -->
      <span v-if="$slots.end" :class="styles.navEnd">
        <slot name="end" />
      </span>
    </button>
    <!-- row -->
    <a
      v-else
      :class="styles.navItem"
      :href="href"
      :aria-current="current ? 'page' : undefined"
      :data-current="current ? '' : undefined"
      @click="(emit('select'), route($event))"
    >
      <!-- glyph -->
      <span v-if="icon !== undefined" :class="styles.navGlyph">
        <Icon :name="icon" />
      </span>
      <!-- label -->
      <span :class="styles.navLabel">
        {{ label }}
      </span>
      <!-- end -->
      <span v-if="$slots.end" :class="styles.navEnd">
        <slot name="end" />
      </span>
    </a>
  </Tooltip>
  <template v-else>
    <!-- row -->
    <button
      v-if="href === undefined"
      :class="styles.navItem"
      type="button"
      :aria-current="current ? 'page' : undefined"
      :data-current="current ? '' : undefined"
      @click="emit('select')"
    >
      <!-- glyph -->
      <span v-if="icon !== undefined" :class="styles.navGlyph">
        <Icon :name="icon" />
      </span>
      <!-- label -->
      <span :class="styles.navLabel">
        {{ label }}
      </span>
      <!-- end -->
      <span v-if="$slots.end" :class="styles.navEnd">
        <slot name="end" />
      </span>
    </button>
    <!-- row -->
    <a
      v-else
      :class="styles.navItem"
      :href="href"
      :aria-current="current ? 'page' : undefined"
      :data-current="current ? '' : undefined"
      @click="(emit('select'), route($event))"
    >
      <!-- glyph -->
      <span v-if="icon !== undefined" :class="styles.navGlyph">
        <Icon :name="icon" />
      </span>
      <!-- label -->
      <span :class="styles.navLabel">
        {{ label }}
      </span>
      <!-- end -->
      <span v-if="$slots.end" :class="styles.navEnd">
        <slot name="end" />
      </span>
    </a>
  </template>
</template>
